// src/components/ReportPage.js
import { useEffect, useState } from 'react'
import { supabase } from '../supabaseClient'
import {
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
  Tooltip,
  Legend
} from 'recharts'

const RADIAN = Math.PI / 180
const COLORS = ['#0088FE','#00C49F','#FFBB28','#FF8042','#AA00FF','#FF3366','#33CCFF','#66CC99','#FF66CC']

export default function ReportPage() {
  const today = new Date()
  const [year, setYear] = useState(today.getFullYear())
  const [month, setMonth] = useState(today.getMonth() + 1)
  const [reportData, setReportData] = useState([])           // 大カテゴリデータ
  const [selectedCategory, setSelectedCategory] = useState(null)
  const [smallCategories, setSmallCategories] = useState([]) // 小カテゴリデータ
  const [loading, setLoading] = useState(false)

  const years = Array.from({ length: 6 }, (_, i) => today.getFullYear() - i)
  const months = Array.from({ length: 12 }, (_, i) => i + 1)

  const formatNumber = (num) => (Number(num) || 0).toLocaleString()

  // グラフ内ラベル: %のみ表示、3%未満は非表示
  const renderLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }) => {
    const pct = percent * 100
    if (pct < 3) return null
    const radius = innerRadius + (outerRadius - innerRadius) * 0.6
    const x = cx + radius * Math.cos(-midAngle * RADIAN)
    const y = cy + radius * Math.sin(-midAngle * RADIAN)
    return (
      <text
        x={x}
        y={y}
        fill="#fff"
        textAnchor="middle"
        dominantBaseline="central"
        style={{ fontSize: 11, fontWeight: 600 }}
      >
        {`${Math.round(pct)}%`}
      </text>
    )
  }

  // 月の範囲を生成
  const monthRange = (y, m) => {
    const start = `${y}-${String(m).padStart(2,'0')}-01`
    const endDate = new Date(y, m, 0).getDate()
    const end = `${y}-${String(m).padStart(2,'0')}-${String(endDate).padStart(2,'0')}`
    return { start, end }
  }

  // 大カテゴリ取得
  useEffect(() => {
    let mounted = true
    setLoading(true)
    const fetchBigCategories = async () => {
      try {
        const { start, end } = monthRange(year, month)
        const { data, error } = await supabase
          .from('expenses')
          .select(`amount, big_category_master (big_category_id, big_category_name)`)
          .or('delete_flg.is.null,delete_flg.eq.false')
          .gte('date', start)
          .lte('date', end)

        if (error) throw error

        const grouped = {}
        (data || []).forEach(item => {
          const id = item.big_category_master?.big_category_id ?? -1
          const name = item.big_category_master?.big_category_name ?? '未分類'
          if (!grouped[id]) grouped[id] = { id, name, value: 0 }
          grouped[id].value += Number(item.amount || 0)
        })

        if (mounted) {
          setReportData(Object.values(grouped).sort((a,b)=>b.value-a.value))
          setSelectedCategory(null)
          setSmallCategories([])
        }
      } catch (err) {
        console.error('fetch big categories error:', err)
      } finally {
        if (mounted) setLoading(false)
      }
    }
    fetchBigCategories()
    return () => { mounted = false }
  }, [year, month])

  // 大カテゴリクリック → 小カテゴリ集計取得
  const handlePieClick = async (entry) => {
    const bigCategoryId = entry?.id
    const bigCategoryName = entry?.name
    if (!bigCategoryId) return

    setSelectedCategory({ id: bigCategoryId, name: bigCategoryName })
    setSmallCategories([])
    setLoading(true)

    try {
      const { start, end } = monthRange(year, month)
      const { data, error } = await supabase
        .from('expenses')
        .select(`amount, small_category_master (small_category_id, small_category_name)`)
        .or('delete_flg.is.null,delete_flg.eq.false')
        .gte('date', start)
        .lte('date', end)
        .eq('big_category_id', bigCategoryId)

      if (error) throw error

      const grouped = {}
      (data || []).forEach(item => {
        const name = item.small_category_master?.small_category_name ?? '未分類'
        grouped[name] = (grouped[name] || 0) + Number(item.amount || 0)
      })

      setSmallCategories(
        Object.entries(grouped)
          .map(([name, value]) => ({ name, value }))
          .sort((a,b)=>b.value-a.value)
      )
    } catch (err) {
      console.error('fetch small categories error:', err)
      setSmallCategories([])
    } finally {
      setLoading(false)
    }
  }

  return (
    <div>
      <h2>月別支出レポート</h2>

      <div style={{ marginBottom: 12 }}>
        <label>年:&nbsp;</label>
        <select value={year} onChange={e => setYear(Number(e.target.value))}>
          {years.map(y => <option key={y} value={y}>{y}</option>)}
        </select>

        <label style={{ marginLeft: 12 }}>月:&nbsp;</label>
        <select value={month} onChange={e => setMonth(Number(e.target.value))}>
          {months.map(m => <option key={m} value={m}>{m}</option>)}
        </select>
      </div>

      {loading && <div>読み込み中...</div>}

      <div style={{ width: '100%', height: 420 }}>
        <ResponsiveContainer>
          <PieChart>
            <Pie
              data={reportData}
              dataKey="value"
              nameKey="name"
              cx="50%"
              cy="50%"
              innerRadius={60}
              outerRadius={120}
              paddingAngle={2}
              labelLine={false}
              label={renderLabel}
              onClick={(entry) => handlePieClick(entry.payload || entry)}
            >
              {reportData.map((entry, idx) => (
                <Cell
                  key={`cell-${entry.id ?? idx}`}
                  fill={COLORS[idx % COLORS.length]}
                  cursor="pointer"
                />
              ))}
            </Pie>
            <Tooltip formatter={(value) => `${formatNumber(value)}円`} />
            <Legend
              verticalAlign="bottom"
              height={60}
              formatter={(value, entry) => {
                const val = entry?.payload?.value ?? 0
                return `${value} : ${formatNumber(val)}円`
              }}
            />
          </PieChart>
        </ResponsiveContainer>
      </div>

      {/* 小カテゴリ表示 */}
      {selectedCategory && (
        <div style={{ marginTop: 20 }}>
          <h3>{selectedCategory.name} の内訳</h3>
          {smallCategories.length === 0 ? (
            <div>データがありません</div>
          ) : (
            <table border="1" cellPadding="6" style={{ borderCollapse: 'collapse', width: '100%' }}>
              <thead>
                <tr>
                  <th style={{ textAlign: 'left' }}>小カテゴリ</th>
                  <th style={{ textAlign: 'right' }}>金額</th>
                </tr>
              </thead>
              <tbody>
                {smallCategories.map(sc => (
                  <tr key={sc.name}>
                    <td>{sc.name}</td>
                    <td style={{ textAlign: 'right' }}>{formatNumber(sc.value)}円</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}
    </div>
  )
}
