import { useEffect, useState } from 'react'
import { supabase } from '../supabaseClient'

export default function ExpenseList({ reload, onEdit }) {
  const [expenses, setExpenses] = useState([])
  const [totalAmount, setTotalAmount] = useState(0) // ← 合計用state

  // 年月選択用の状態
  const today = new Date()
  const [selectedYear, setSelectedYear] = useState(today.getFullYear())
  const [selectedMonth, setSelectedMonth] = useState(today.getMonth() + 1) // 1～12

  const years = Array.from({ length: 5 }, (_, i) => today.getFullYear() - i) // 過去5年
  const months = Array.from({ length: 12 }, (_, i) => i + 1)

  // supabaseから支出データを取得
  useEffect(() => {
    async function fetchExpenses() {
      const monthStart = `${selectedYear}-${String(selectedMonth).padStart(2, '0')}-01`
      const monthEndDate = new Date(selectedYear, selectedMonth, 0).getDate() // 月末
      const monthEnd = `${selectedYear}-${String(selectedMonth).padStart(2, '0')}-${monthEndDate}`

      const { data, error } = await supabase
        .from('expenses')
        .select(`
          id,
          date,
          note,
          amount,
          big_category_master (big_category_id, big_category_name),
          small_category_master (small_category_id, small_category_name),
          delete_flg
        `)
        .or('delete_flg.is.null,delete_flg.eq.false')
        .gte('date', monthStart)
        .lte('date', monthEnd)
        .order('date', { ascending: false })

      if (!error) {
        const filtered = data.filter(e => !e.delete_flg)
        setExpenses(filtered)
        const total = filtered.reduce((sum, e) => sum + Number(e.amount || 0), 0)
        setTotalAmount(total) // ← 合計をセット
      } else {
        setExpenses([])
        setTotalAmount(0)
      }
    }

    fetchExpenses()
  }, [reload, selectedYear, selectedMonth])

  return (
    <div>
      <h2>支出一覧</h2>

      {/* 年月プルダウン＋合計金額 */}
      <div style={{ marginBottom: '10px' }}>
        <label>年: </label>
        <select value={selectedYear} onChange={e => setSelectedYear(Number(e.target.value))}>
          {years.map(y => <option key={y} value={y}>{y}</option>)}
        </select>

        <label style={{ marginLeft: '10px' }}>月: </label>
        <select value={selectedMonth} onChange={e => setSelectedMonth(Number(e.target.value))}>
          {months.map(m => <option key={m} value={m}>{m}</option>)}
        </select>

        <span style={{ marginLeft: '20px', fontWeight: 'bold' }}>
          合計: {totalAmount.toLocaleString()}円
        </span>
      </div>

      <table border="1" cellPadding="5" style={{ width: '100%', borderCollapse: 'collapse' }}>
        <thead>
          <tr>
            <th>日付</th>
            <th>大カテゴリ</th>
            <th>小カテゴリ</th>
            <th>備考</th>
            <th>金額</th>
            <th>操作</th>
          </tr>
        </thead>
        <tbody>
          {expenses.length === 0 ? (
            <tr>
              <td colSpan="6">データがありません</td>
            </tr>
          ) : (
            expenses.map(exp => (
              <tr key={exp.id}>
                <td>{exp.date}</td>
                <td>{exp.big_category_master?.big_category_name}</td>
                <td>{exp.small_category_master?.small_category_name}</td>
                <td>{exp.note}</td>
                <td style={{ textAlign: 'right' }}>{Number(exp.amount).toLocaleString()}円</td>
                <td>
                  <button onClick={() => onEdit(exp)}>編集</button>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  )
}
